<?php
namespace App\Console\Commands; use App\Services\Dapcode\CodeFormatterService; use App\Services\Dapcode\CodeMinifierService; use Illuminate\Console\Command; use Illuminate\Support\Str; class CodeUnminifyCommand extends Command { protected $signature = 'code:unminify
                            {target=all : Target: "all", "modules", "aegisguard", "routes", module name (e.g. "Achievement"), or custom path}
                            {--format : Force reformatting using code beautifier without reading vault}
                            {--indent=4 : Number of spaces for indentation (default: 4)}
                            {--clean-backup : Clear vaulted sourcemaps/backups after successful restore}
                            {--force : Force operation without confirmation}'; protected $description = 'Unminify, restore original code from SourceMap Vault, or beautify code'; public function handle(CodeMinifierService $minifier, CodeFormatterService $formatter) { $target = (string) $this->argument('target'); $forceFormat = (bool) $this->option('format'); $indent = (int) $this->option('indent'); $cleanBackup = (bool) $this->option('clean-backup'); $force = (bool) $this->option('force'); $this->info("======================================================="); $this->info("     DAPCODE AEGISGUARD — PHP CODE UNMINIFIER          "); $this->info("======================================================="); $this->line("<comment>Target:</comment> <info>{$target}</info>"); $this->line("<comment>Mode  :</comment> " . ($forceFormat ? '<comment>Force Code Beautifier/Formatter</comment>' : '<info>Auto (Restore from Vault if available, else Beautify)</info>')); $this->line("<comment>Indent:</comment> <info>{$indent} spaces</info>"); $this->newLine(); $files = $minifier->getTargetFiles($target); if (empty($files)) { $this->error("Tidak ada file PHP yang ditemukan untuk target [{$target}]."); return 1; } $this->line("Ditemukan <info>" . count($files) . "</info> file target."); if (! $force && count($files) > 10 && $this->input->isInteractive()) { if (! $this->confirm("Apakah Anda yakin ingin me-unminify / memformat " . count($files) . " file PHP ini?", true)) { $this->warn("Operasi dibatalkan oleh pengguna."); return 0; } } $results = []; $restoredVaultCount = 0; $restoredBakCount = 0; $beautifiedCount = 0; $bar = $this->output->createProgressBar(count($files)); $bar->start(); foreach ($files as $file) { $res = $formatter->unminifyFile($file, ! $forceFormat, $forceFormat, $indent, $cleanBackup ); if ($res['success']) { $relPath = Str::after($file, base_path() . DIRECTORY_SEPARATOR); if ($res['mode'] === 'vault_restored') { $restoredVaultCount++; $status = '<info>Restored (Vault)</info>'; } elseif ($res['mode'] === 'backup_restored') { $restoredBakCount++; $status = '<info>Restored (.bak)</info>'; } else { $beautifiedCount++; $status = '<comment>Beautified</comment>'; } $results[] = [ 'file' => $relPath, 'type' => '<comment>PHP</comment>', 'status' => $status, 'size' => $this->formatBytes($res['size']), ]; } $bar->advance(); } $bar->finish(); $this->newLine(2); $this->table(['File Target', 'Type', 'Action / Status', 'New Size'], $results ); $this->info("======================================================="); $this->info(" [SELESAI] " . count($results) . " file berhasil di-unminify!"); $this->line(" Dipulihkan dari SourceMap Vault : <info>{$restoredVaultCount}</info> file (100% kode asli)"); if ($restoredBakCount > 0) { $this->line(" Dipulihkan dari file .bak       : <info>{$restoredBakCount}</info> file"); } $this->line(" Diformat ulang (Beautifier)     : <info>{$beautifiedCount}</info> file"); if ($cleanBackup) { $this->line(" Vault sourcemaps / file .bak telah dibersihkan."); } $this->info("======================================================="); return 0; } protected function formatBytes($bytes, $precision = 2) { if ($bytes <= 0) { return '0 B'; } $units = ['B', 'KB', 'MB', 'GB']; $base = log($bytes, 1024); $pow = floor($base); return round(pow(1024, $base - $pow), $precision) . ' ' . ($units[$pow] ?? 'B'); } }